        break
    else:
        continue
    break

def to_minutes(hhmm):
    h, m = map(int, hhmm.split(":"))
    return h * 60 + m


def to_hhmm(minutes):
    return f"{minutes // 60:02d}:{minutes % 60:02d}"


def main():
    days = ["Monday", "Tuesday", "Wednesday", "Thursday"]
    work_start = to_minutes("09:00")
    work_end = to_minutes("17:00")
    duration = 30
    avoid_days = {"Wednesday", "Thursday"}

    busy = {
        "Cheryl": {day: [] for day in days},
        "James": {
            "Monday": [
                ("09:00", "09:30"),
                ("10:30", "11:00"),
                ("12:30", "13:00"),
                ("14:30", "15:30"),
                ("16:30", "17:00"),
            ],
            "Tuesday": [
                ("09:00", "11:00"),
                ("11:30", "12:00"),
                ("12:30", "15:30"),
                ("16:00", "17:00"),
            ],
            "Wednesday": [
                ("10:00", "11:00"),
                ("12:00", "13:00"),
                ("13:30", "16:00"),
            ],
            "Thursday": [
                ("09:30", "11:30"),
                ("12:00", "12:30"),
                ("13:00", "13:30"),
                ("14:00", "14:30"),
                ("16:30", "17:00"),
            ],
        },
    }

    busy_minutes = {
        person: {
            day: [(to_minutes(start), to_minutes(end)) for start, end in intervals]
            for day, intervals in day_map.items()
        }
        for person, day_map in busy.items()
    }

    def feasible(day, start):
        end = start + duration
        if start < work_start or end > work_end:
            return False

        for person in busy_minutes:
            for busy_start, busy_end in busy_minutes[person][day]:
                if start < busy_end and busy_start < end:
                    return False

        return True

    fallback = None

    for day in days:
        for start in range(work_start, work_end - duration + 1):
            if not feasible(day, start):
                continue

            if day not in avoid_days:
                print([day, to_hhmm(start), to_hhmm(start + duration)])
                return

            if fallback is None:
                fallback = (day, start)

    if fallback is not None:
        day, start = fallback
        print([day, to_hhmm(start), to_hhmm(start + duration)])


if __name__ == "__main__":
    main()
